from __future__ import annotations
from itertools import product
from typing import Any, Callable

# ---------------------------------------------------------------------------
# Domain and Interpretation
# ---------------------------------------------------------------------------

Domain = list[str]
Assignment = dict[str, str]  # variable name -> domain element


class Interpretation:
    """A FOL interpretation over a finite domain.

    predicates: mapping from predicate name to a set of tuples.
      e.g. {"Doctor": {("alice",), ("bob",)},
            "Treats":  {("alice", "carol"), ("bob", "carol")}}
    """

    def __init__(self, domain: Domain, predicates: dict[str, set[tuple]]):
        self.domain = domain
        self.predicates = predicates

    def holds(self, name: str, args: tuple[str, ...]) -> bool:
        return args in self.predicates.get(name, set())


# ---------------------------------------------------------------------------
# Formula AST nodes
# ---------------------------------------------------------------------------

class Formula:
    """Abstract base for FOL formulas."""

    def evaluate(self, interp: Interpretation, assign: Assignment) -> bool:
        raise NotImplementedError

    def __repr__(self) -> str:
        return self.__class__.__name__


class Atom(Formula):
    """Atomic formula: P(t1, ..., tn) where each ti is a var or constant."""

    def __init__(self, predicate: str, *args: str):
        self.predicate = predicate
        self.args = args  # strings: lowercase = var, Uppercase first = constant

    def _resolve(self, term: str, assign: Assignment) -> str:
        # If it starts with a lowercase letter, it's a variable
        if term[0].islower() and term in assign:
            return assign[term]
        return term  # constant

    def evaluate(self, interp: Interpretation, assign: Assignment) -> bool:
        resolved = tuple(self._resolve(t, assign) for t in self.args)
        return interp.holds(self.predicate, resolved)

    def __repr__(self) -> str:
        return f"{self.predicate}({', '.join(self.args)})"


class Not(Formula):
    def __init__(self, operand: Formula):
        self.operand = operand

    def evaluate(self, interp: Interpretation, assign: Assignment) -> bool:
        return not self.operand.evaluate(interp, assign)

    def __repr__(self) -> str:
        return f"NOT({self.operand})"


class And(Formula):
    def __init__(self, *operands: Formula):
        self.operands = operands

    def evaluate(self, interp: Interpretation, assign: Assignment) -> bool:
        return all(op.evaluate(interp, assign) for op in self.operands)

    def __repr__(self) -> str:
        return " AND ".join(repr(op) for op in self.operands)


class Or(Formula):
    def __init__(self, *operands: Formula):
        self.operands = operands

    def evaluate(self, interp: Interpretation, assign: Assignment) -> bool:
        return any(op.evaluate(interp, assign) for op in self.operands)


class Implies(Formula):
    def __init__(self, antecedent: Formula, consequent: Formula):
        self.antecedent = antecedent
        self.consequent = consequent

    def evaluate(self, interp: Interpretation, assign: Assignment) -> bool:
        return (
            not self.antecedent.evaluate(interp, assign)
            or self.consequent.evaluate(interp, assign)
        )

    def __repr__(self) -> str:
        return f"({self.antecedent} -> {self.consequent})"


class ForAll(Formula):
    """Universal quantifier: ForAll(var, formula)."""

    def __init__(self, variable: str, body: Formula):
        self.variable = variable
        self.body = body

    def evaluate(self, interp: Interpretation, assign: Assignment) -> bool:
        for elem in interp.domain:
            new_assign = {**assign, self.variable: elem}
            if not self.body.evaluate(interp, new_assign):
                return False
        return True

    def __repr__(self) -> str:
        return f"∀{self.variable}. {self.body}"


class Exists(Formula):
    """Existential quantifier: Exists(var, formula)."""

    def __init__(self, variable: str, body: Formula):
        self.variable = variable
        self.body = body

    def evaluate(self, interp: Interpretation, assign: Assignment) -> bool:
        for elem in interp.domain:
            new_assign = {**assign, self.variable: elem}
            if self.body.evaluate(interp, new_assign):
                return True
        return False

    def __repr__(self) -> str:
        return f"∃{self.variable}. {self.body}"


# ---------------------------------------------------------------------------
# Entailment checker
# ---------------------------------------------------------------------------

def check_entailment(
    axioms: list[Formula],
    query: Formula,
    interp: Interpretation,
) -> dict:
    """Check whether axioms entail query in the given interpretation."""
    empty: Assignment = {}
    axioms_hold = all(ax.evaluate(interp, empty) for ax in axioms)
    query_holds = query.evaluate(interp, empty)
    return {
        "axioms_satisfied": axioms_hold,
        "query_holds": query_holds,
        "entailment_valid": axioms_hold and query_holds,
    }


# ---------------------------------------------------------------------------
# Demo: small medical domain
# ---------------------------------------------------------------------------

def main():
    # Domain: alice is a surgeon, bob is a nurse, carol is a patient
    domain: Domain = ["alice", "bob", "carol"]

    interp = Interpretation(
        domain=domain,
        predicates={
            "Surgeon":  {("alice",)},
            "Nurse":    {("bob",)},
            "Patient":  {("carol",)},
            "Doctor":   {("alice",)},           # alice is also a Doctor
            "Treats":   {("alice", "carol"),     # alice treats carol
                         ("bob",   "carol")},    # bob also treats carol
            "HasCRM":   {("alice", "crm-12345")},
        },
    )

    # Axiom 1: Every Surgeon is a Doctor
    # ∀x. Surgeon(x) → Doctor(x)
    axiom1 = ForAll("x", Implies(Atom("Surgeon", "x"), Atom("Doctor", "x")))

    # Axiom 2: Every Doctor treats at least one Patient
    # ∀x. Doctor(x) → ∃y. (Patient(y) ∧ Treats(x, y))
    axiom2 = ForAll(
        "x",
        Implies(
            Atom("Doctor", "x"),
            Exists("y", And(Atom("Patient", "y"), Atom("Treats", "x", "y"))),
        ),
    )

    # Axiom 3: Doctors and Nurses are disjoint
    # ∀x. Doctor(x) → ¬Nurse(x)
    axiom3 = ForAll("x", Implies(Atom("Doctor", "x"), Not(Atom("Nurse", "x"))))

    axioms = [axiom1, axiom2, axiom3]

    # Query: Does there exist a Doctor who treats Carol?
    # ∃x. Doctor(x) ∧ Treats(x, carol)
    query = Exists("x", And(Atom("Doctor", "x"), Atom("Treats", "x", "carol")))

    result = check_entailment(axioms, query, interp)

    print("=" * 60)
    print("FOL Satisfiability Checker — Medical Domain")
    print("=" * 60)
    print(f"Domain: {interp.domain}")
    print()
    print("Axioms:")
    for i, ax in enumerate(axioms, 1):
        print(f"  [{i}] {ax}")
    print()
    print(f"Query:  {query}")
    print()
    print("Results:")
    for k, v in result.items():
        print(f"  {k}: {v}")

    # Also demonstrate: check each axiom individually
    print()
    print("Individual axiom evaluation:")
    empty: Assignment = {}
    for i, ax in enumerate(axioms, 1):
        val = ax.evaluate(interp, empty)
        print(f"  Axiom {i} holds in I: {val}")


if __name__ == "__main__":
    main()
